// Package machine rebuilds each agent machine from stored traces.
//
// shy logs every bash, write, and edit. Those calls are what changed the
// machine. Replay walks them in order and keeps the files and the services
// they imply: compose files, units, process files, and commands that leave
// something running after they return.
package machine

import (
	"bytes"
	"encoding/json"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	// Running means a command left the service up: detached, a service
	// manager, or a background process.
	Running = "running"
	// Stopped means a later command brought it down.
	Stopped = "stopped"
	// Declared means a file defines it and nothing has started it.
	Declared = "declared"

	maxDepth    = 64
	maxNodes    = 10000
	maxFileBody = 512 << 10
	maxCommand  = 64 << 10
	maxShowSvc  = 60
	maxShowFile = 80
)

// Run is one stored trace for one agent.
type Run struct {
	InstallID int64
	Install   string
	Payload   []byte
}

// Snapshot is one agent's machine after replaying its runs oldest first.
type Snapshot struct {
	Agent    string
	Summary  string
	Clusters []Cluster
	Files    []File
}

// Cluster is one file or one way of starting processes.
type Cluster struct {
	Title    string
	Services []Service
}

// Service is one process, container, or unit on the machine.
type Service struct {
	Name   string
	Kind   string
	State  string
	Port   string
	Detail string
}

// File is a path a run wrote or edited.
type File struct {
	Path string
	Op   string
}

type fileRec struct {
	Path string
	Op   string
	Body string
	Have bool
	Kind string
}

type svc struct {
	Key    string
	Name   string
	Kind   string
	State  string
	Port   string
	Detail string
	Group  string
}

type draft struct {
	Name   string
	Kind   string
	Port   string
	Detail string
}

type world struct {
	agent string
	files map[string]*fileRec
	order []string
	svcs  []*svc
}

// Replay groups runs by agent and rebuilds each machine.
// InstallID separates agents. Runs must already be oldest first.
func Replay(runs []Run) []Snapshot {
	var keys []string
	worlds := map[string]*world{}
	for _, r := range runs {
		if len(bytes.TrimSpace(r.Payload)) == 0 {
			continue
		}
		k := strconv.FormatInt(r.InstallID, 10)
		if r.InstallID == 0 {
			k = "0:" + r.Install
		}
		w := worlds[k]
		if w == nil {
			w = newWorld(r.Install)
			worlds[k] = w
			keys = append(keys, k)
		}
		w.replay(r.Payload)
	}
	var out []Snapshot
	for _, k := range keys {
		out = append(out, worlds[k].snapshot())
	}
	return out
}

func newWorld(agent string) *world {
	agent = strings.TrimSpace(agent)
	if agent == "" {
		agent = "agent"
	}
	return &world{agent: agent, files: map[string]*fileRec{}}
}

func (w *world) replay(payload []byte) {
	dec := json.NewDecoder(bytes.NewReader(payload))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return
	}
	n := 0
	walk(v, w, 0, &n)
}

func walk(v any, w *world, depth int, nodes *int) {
	if depth > maxDepth || *nodes >= maxNodes {
		return
	}
	m, ok := v.(map[string]any)
	if !ok {
		return
	}
	*nodes++
	w.tool(m)
	kids, _ := m["children"].([]any)
	for _, c := range kids {
		walk(c, w, depth+1, nodes)
	}
}

func (w *world) tool(m map[string]any) {
	if !strings.EqualFold(str(m["kind"]), "TOOL") {
		return
	}
	if strings.EqualFold(str(m["status"]), "ERROR") {
		return
	}
	name := str(m["tool_name"])
	if name == "" {
		name = str(m["name"])
	}
	in := object(m["input"])
	switch name {
	case "write":
		w.writeFile(field(in, "path"), field(in, "content"), "write")
	case "edit":
		w.editFile(field(in, "path"), field(in, "oldText"), field(in, "newText"))
	case "bash":
		w.bash(field(in, "command"))
	}
}

func (w *world) writeFile(path, content, op string) {
	path = clean(path)
	if path == "" {
		return
	}
	rec := w.files[path]
	if rec == nil {
		rec = &fileRec{Path: path}
		w.files[path] = rec
	}
	rec.Op = op
	rec.Kind = manifestKind(path)
	if rec.Kind != "" && len(content) <= maxFileBody {
		rec.Body = content
		rec.Have = true
		w.extract(path, content)
	} else {
		rec.Body = ""
		rec.Have = false
		if rec.Kind == "" {
			w.dropGroup(path, false)
		}
	}
	w.touchOrder(path)
}

func (w *world) editFile(path, old, new string) {
	path = clean(path)
	if path == "" {
		return
	}
	rec := w.files[path]
	if rec == nil {
		rec = &fileRec{Path: path, Op: "edit", Kind: manifestKind(path)}
		w.files[path] = rec
		w.touchOrder(path)
		return
	}
	rec.Op = "edit"
	w.touchOrder(path)
	if !rec.Have || old == "" || strings.Count(rec.Body, old) != 1 {
		return
	}
	rec.Body = strings.Replace(rec.Body, old, new, 1)
	if manifestKind(path) != "" {
		rec.Kind = manifestKind(path)
		w.extract(path, rec.Body)
	}
}

func (w *world) extract(path, body string) {
	var items []draft
	switch manifestKind(path) {
	case "compose":
		items = parseCompose(body)
	case "unit":
		items = parseUnit(path, body)
	case "procfile":
		items = parseProcfile(body)
	case "caddy":
		items = parseCaddy(body)
	case "package":
		items = parsePackage(path, body)
	}
	w.setFileServices(path, items)
}

func (w *world) setFileServices(group string, items []draft) {
	prev := map[string]string{}
	for _, s := range w.svcs {
		if s.Group == group {
			prev[s.Name] = s.State
		}
	}
	var fresh []*svc
	seen := map[string]bool{}
	for _, it := range items {
		if it.Name == "" || seen[it.Name] {
			continue
		}
		seen[it.Name] = true
		state := Declared
		if p, ok := prev[it.Name]; ok {
			state = p
		}
		fresh = append(fresh, &svc{
			Key:    group + "\x00" + it.Name,
			Name:   it.Name,
			Kind:   it.Kind,
			State:  state,
			Port:   it.Port,
			Detail: it.Detail,
			Group:  group,
		})
	}
	old := append([]*svc(nil), w.svcs...)
	var next []*svc
	inserted := false
	for _, s := range old {
		if s.Group != group {
			next = append(next, s)
			continue
		}
		if !inserted {
			next = append(next, fresh...)
			inserted = true
		}
	}
	if !inserted {
		next = append(next, fresh...)
	}
	w.svcs = next
}

// dropGroup removes services defined by path.
// Running ones stay, under a group that does not depend on the file,
// because deleting the file does not stop a process that is already up.
func (w *world) dropGroup(path string, keepRunning bool) {
	var next []*svc
	for _, s := range w.svcs {
		if s.Group != path {
			next = append(next, s)
			continue
		}
		if keepRunning && s.State == Running {
			s.Group = leftoverGroup(s.Kind)
			s.Key = s.Group + "\x00" + s.Name
			next = append(next, s)
		}
	}
	w.svcs = next
}

func leftoverGroup(kind string) string {
	switch kind {
	case "unit":
		return "Units"
	case "process", "http", "app":
		return "Shell"
	default:
		return "Containers"
	}
}

func (w *world) bash(cmd string) {
	if len(cmd) > maxCommand {
		cmd = cmd[:maxCommand]
	}
	for _, c := range parseCommands(cmd) {
		for _, inner := range expand(c.argv, c.bg, 0) {
			w.exec(inner.argv, inner.bg)
		}
	}
}

func (w *world) touchOrder(path string) {
	w.removeOrder(path)
	w.order = append(w.order, path)
}

func (w *world) removeOrder(path string) {
	next := make([]string, 0, len(w.order))
	for _, p := range w.order {
		if p != path {
			next = append(next, p)
		}
	}
	w.order = next
}

func (w *world) deletePath(p string) {
	p = clean(p)
	if p == "" || p == "." || p == "/" || strings.ContainsAny(p, "*?[") {
		return
	}
	if _, ok := w.files[p]; ok {
		w.dropFile(p)
	}
	var nested []string
	for _, path := range w.order {
		if strings.HasPrefix(path, p+"/") {
			nested = append(nested, path)
		}
	}
	for _, path := range nested {
		w.dropFile(path)
	}
}

func (w *world) dropFile(path string) {
	delete(w.files, path)
	w.removeOrder(path)
	w.dropGroup(path, true)
}

func (w *world) rename(src, dst string) {
	src, dst = clean(src), clean(dst)
	if src == "" || dst == "" || src == dst || strings.ContainsAny(src, "*?[") || strings.ContainsAny(dst, "*?[") {
		return
	}
	if _, ok := w.files[src]; ok {
		w.moveOne(src, dst)
		return
	}
	var paths []string
	for _, p := range w.order {
		if strings.HasPrefix(p, src+"/") {
			paths = append(paths, p)
		}
	}
	for _, p := range paths {
		w.moveOne(p, dst+"/"+strings.TrimPrefix(p, src+"/"))
	}
}

func (w *world) moveOne(src, dst string) {
	rec := w.files[src]
	if rec == nil {
		return
	}
	delete(w.files, src)
	w.removeOrder(src)
	rec.Path = dst
	rec.Kind = manifestKind(dst)
	w.files[dst] = rec
	w.touchOrder(dst)
	if rec.Kind != "" && rec.Have {
		for _, s := range w.svcs {
			if s.Group == src {
				s.Group = dst
				s.Key = dst + "\x00" + s.Name
			}
		}
		w.extract(dst, rec.Body)
		return
	}
	w.dropGroup(src, true)
}

func (w *world) copyPath(src, dst string) {
	src, dst = clean(src), clean(dst)
	if src == "" || dst == "" || strings.ContainsAny(src, "*?[") || strings.ContainsAny(dst, "*?[") {
		return
	}
	if _, ok := w.files[src]; ok {
		w.copyOne(src, dst)
		return
	}
	var paths []string
	for _, p := range w.order {
		if strings.HasPrefix(p, src+"/") {
			paths = append(paths, p)
		}
	}
	for _, p := range paths {
		w.copyOne(p, dst+"/"+strings.TrimPrefix(p, src+"/"))
	}
}

func (w *world) copyOne(src, dst string) {
	rec := w.files[src]
	if rec == nil {
		return
	}
	dup := *rec
	dup.Path = dst
	dup.Op = "write"
	dup.Kind = manifestKind(dst)
	w.files[dst] = &dup
	w.touchOrder(dst)
	if dup.Have && dup.Kind != "" {
		w.extract(dst, dup.Body)
	}
}

func (w *world) touch(path string) {
	path = clean(path)
	if path == "" || strings.ContainsAny(path, "*?[") {
		return
	}
	if _, ok := w.files[path]; ok {
		return
	}
	w.files[path] = &fileRec{Path: path, Op: "write"}
	w.touchOrder(path)
}

func (w *world) servicesIn(path string) []*svc {
	if path == "" {
		return nil
	}
	var out []*svc
	for _, s := range w.svcs {
		if s.Group == path {
			out = append(out, s)
		}
	}
	return out
}

func (w *world) findKey(key string) *svc {
	for _, s := range w.svcs {
		if s.Key == key {
			return s
		}
	}
	return nil
}

func (w *world) resolveCompose(flag string) string {
	if flag != "" {
		for i := len(w.order) - 1; i >= 0; i-- {
			p := w.order[i]
			rec := w.files[p]
			if rec != nil && rec.Kind == "compose" && samePath(p, flag) {
				return p
			}
		}
		return ""
	}
	for i := len(w.order) - 1; i >= 0; i-- {
		p := w.order[i]
		if rec := w.files[p]; rec != nil && rec.Kind == "compose" {
			return p
		}
	}
	return ""
}

func (w *world) snapshot() Snapshot {
	var clusters []Cluster
	groups := map[string]int{}
	n := 0
	for _, s := range w.svcs {
		if n >= maxShowSvc {
			break
		}
		i, ok := groups[s.Group]
		if !ok {
			i = len(clusters)
			groups[s.Group] = i
			clusters = append(clusters, Cluster{Title: s.Group})
		}
		clusters[i].Services = append(clusters[i].Services, Service{
			Name:   clip(s.Name, 80),
			Kind:   s.Kind,
			State:  s.State,
			Port:   clip(s.Port, 80),
			Detail: clip(s.Detail, 140),
		})
		n++
	}
	var files []File
	for i := len(w.order) - 1; i >= 0 && len(files) < maxShowFile; i-- {
		rec := w.files[w.order[i]]
		if rec == nil {
			continue
		}
		files = append(files, File{Path: clip(rec.Path, 180), Op: rec.Op})
	}
	return Snapshot{
		Agent:    w.agent,
		Summary:  summarize(clusters, len(files)),
		Clusters: clusters,
		Files:    files,
	}
}

func summarize(clusters []Cluster, files int) string {
	var run, stop, decl int
	for _, c := range clusters {
		for _, s := range c.Services {
			switch s.State {
			case Running:
				run++
			case Stopped:
				stop++
			default:
				decl++
			}
		}
	}
	var parts []string
	if run > 0 {
		parts = append(parts, plural(run, "running"))
	}
	if stop > 0 {
		parts = append(parts, plural(stop, "stopped"))
	}
	if decl > 0 {
		parts = append(parts, plural(decl, "declared"))
	}
	if files > 0 {
		parts = append(parts, plural(files, "file"))
	}
	if len(parts) == 0 {
		return "No services or files in the stored runs."
	}
	return strings.Join(parts, " · ")
}

func plural(n int, word string) string {
	if word == "file" && n != 1 {
		word = "files"
	}
	return strconv.Itoa(n) + " " + word
}

func object(v any) map[string]any {
	switch t := v.(type) {
	case map[string]any:
		return t
	case string:
		var m map[string]any
		if json.Unmarshal([]byte(t), &m) == nil {
			return m
		}
	}
	return nil
}

func str(v any) string {
	s, _ := v.(string)
	return s
}

func field(m map[string]any, k string) string {
	if m == nil {
		return ""
	}
	return str(m[k])
}

func clip(s string, n int) string {
	s = strings.TrimSpace(s)
	if n < 1 || utf8.RuneCountInString(s) <= n {
		return s
	}
	return string([]rune(s)[:n]) + "…"
}

func clean(p string) string {
	p = strings.TrimSpace(p)
	p = strings.ReplaceAll(p, "\\", "/")
	for strings.HasPrefix(p, "./") {
		p = strings.TrimPrefix(p, "./")
	}
	return strings.TrimRight(p, "/")
}

func baseName(path string) string {
	path = clean(path)
	if i := strings.LastIndex(path, "/"); i >= 0 {
		return path[i+1:]
	}
	return path
}

func samePath(a, b string) bool {
	a, b = clean(a), clean(b)
	if a == "" || b == "" {
		return false
	}
	return a == b || strings.HasSuffix(a, "/"+b) || strings.HasSuffix(b, "/"+a)
}

func manifestKind(path string) string {
	b := strings.ToLower(baseName(path))
	switch b {
	case "compose.yaml", "compose.yml", "docker-compose.yaml", "docker-compose.yml":
		return "compose"
	case "procfile":
		return "procfile"
	case "caddyfile":
		return "caddy"
	case "package.json":
		return "package"
	}
	if strings.HasSuffix(b, ".service") {
		return "unit"
	}
	return ""
}

package machine

import "strings"

type tokKind int

const (
	tokWord tokKind = iota
	tokAnd
	tokOr
	tokSemi
	tokPipe
	tokAmp
	tokNL
)

type token struct {
	kind tokKind
	val  string
}

type command struct {
	argv []string
	bg   bool
}

func parseCommands(s string) []command {
	toks := tokenize(s)
	var out []command
	var cur []string
	skip := false
	flush := func(bg bool) {
		if !skip && len(cur) > 0 {
			out = append(out, command{argv: append([]string(nil), cur...), bg: bg})
		}
		cur = nil
		skip = false
	}
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		switch t.kind {
		case tokWord:
			bare, red := redirectForm(t.val)
			if red {
				if bare && i+1 < len(toks) && toks[i+1].kind == tokWord {
					i++
				}
				continue
			}
			if !skip {
				cur = append(cur, t.val)
			}
		case tokAnd, tokSemi, tokPipe, tokNL:
			flush(false)
		case tokOr:
			flush(false)
			skip = true
		case tokAmp:
			flush(true)
		}
	}
	flush(false)
	return out
}

func tokenize(s string) []token {
	var out []token
	i := 0
	for i < len(s) {
		if len(out) > 500 {
			break
		}
		switch s[i] {
		case ' ', '\t', '\r':
			i++
		case '\n':
			out = append(out, token{kind: tokNL})
			i++
		case '&':
			if i+1 < len(s) && s[i+1] == '&' {
				out = append(out, token{kind: tokAnd})
				i += 2
				continue
			}
			if i+1 < len(s) && s[i+1] == '>' {
				word, next := scanWord(s, i)
				if next <= i {
					i++
					continue
				}
				if word != "" {
					out = append(out, token{kind: tokWord, val: word})
				}
				i = next
				continue
			}
			out = append(out, token{kind: tokAmp})
			i++
		case '|':
			if i+1 < len(s) && s[i+1] == '|' {
				out = append(out, token{kind: tokOr})
				i += 2
				continue
			}
			out = append(out, token{kind: tokPipe})
			i++
		case ';':
			out = append(out, token{kind: tokSemi})
			i++
		default:
			word, next := scanWord(s, i)
			if next <= i {
				i++
				continue
			}
			if word != "" {
				out = append(out, token{kind: tokWord, val: word})
			}
			i = next
		}
	}
	return out
}

func scanWord(s string, i int) (string, int) {
	var b strings.Builder
	for i < len(s) {
		c := s[i]
		switch c {
		case '\\':
			if i+1 < len(s) {
				b.WriteByte(s[i+1])
				i += 2
				continue
			}
			b.WriteByte(c)
			i++
		case '\'':
			i++
			for i < len(s) && s[i] != '\'' {
				b.WriteByte(s[i])
				i++
			}
			if i < len(s) {
				i++
			}
		case '"':
			i++
			for i < len(s) && s[i] != '"' {
				if s[i] == '\\' && i+1 < len(s) {
					n := s[i+1]
					if n == '"' || n == '\\' || n == '$' || n == '`' || n == '\n' {
						b.WriteByte(n)
						i += 2
						continue
					}
				}
				b.WriteByte(s[i])
				i++
			}
			if i < len(s) {
				i++
			}
		case ' ', '\t', '\n', '\r', ';', '|':
			return b.String(), i
		case '&':
			if b.Len() > 0 && strings.HasSuffix(b.String(), ">") {
				b.WriteByte('&')
				i++
				continue
			}
			return b.String(), i
		default:
			b.WriteByte(c)
			i++
		}
	}
	return b.String(), i
}

func redirectForm(s string) (bare, ok bool) {
	if s == "" {
		return false, false
	}
	i := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i < len(s) {
		op := s[i:]
		switch {
		case strings.HasPrefix(op, ">>"):
			return op == ">>", true
		case strings.HasPrefix(op, ">&"):
			return op == ">&", true
		case strings.HasPrefix(op, ">"):
			return op == ">", true
		case strings.HasPrefix(op, "<<"):
			return op == "<<", true
		case strings.HasPrefix(op, "<"):
			return op == "<", true
		}
	}
	switch {
	case strings.HasPrefix(s, "&>>"):
		return s == "&>>", true
	case strings.HasPrefix(s, "&>"):
		return s == "&>", true
	}
	return false, false
}

func expand(argv []string, bg bool, depth int) []command {
	if len(argv) == 0 {
		return nil
	}
	if depth > 3 {
		return []command{{argv: argv, bg: bg}}
	}
	script, ok := bashScript(argv)
	if !ok {
		return []command{{argv: argv, bg: bg}}
	}
	var out []command
	for _, c := range parseCommands(script) {
		out = append(out, expand(c.argv, c.bg || bg, depth+1)...)
	}
	return out
}

func bashScript(argv []string) (string, bool) {
	if len(argv) == 0 || !isShell(argv[0]) {
		return "", false
	}
	for i := 1; i < len(argv); i++ {
		a := argv[i]
		if a == "-c" || (strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") && strings.Contains(a, "c")) {
			if i+1 < len(argv) {
				return argv[i+1], true
			}
			return "", false
		}
		if a == "--" {
			break
		}
	}
	return "", false
}

func isShell(name string) bool {
	name = baseName(name)
	return name == "bash" || name == "sh"
}

func (w *world) exec(argv []string, bg bool) {
	argv = stripWrappers(argv, &bg)
	if len(argv) == 0 || boring(argv[0]) {
		return
	}
	switch argv[0] {
	case "rm":
		for _, a := range positionals(argv[1:]) {
			w.deletePath(a)
		}
	case "mv":
		w.mv(positionals(argv[1:]))
	case "cp":
		w.cp(positionals(argv[1:]))
	case "touch":
		for _, a := range positionals(argv[1:]) {
			w.touch(a)
		}
	case "mkdir", "chmod", "chown", "ln":
		return
	case "docker", "podman":
		w.docker(argv, bg)
	case "docker-compose", "podman-compose":
		w.compose(argv[1:], bg)
	case "systemctl":
		w.systemctl(argv[1:])
	case "service":
		w.sysv(argv[1:])
	case "caddy":
		w.caddy(argv[1:], bg)
	case "npm", "pnpm", "yarn", "bun":
		if w.node(argv, bg) {
			return
		}
		if bg {
			w.background(argv)
		}
	case "kill", "killall", "pkill":
		w.kill(argv)
	default:
		if bg {
			w.background(argv)
		}
	}
}

func boring(name string) bool {
	switch baseName(name) {
	case "cd", "pushd", "popd", "export", "unset", "alias", "unalias", "set", "ulimit", "hash", "umask",
		"true", "false", ":", "echo", "printf", "pwd", "ls", "cat", "which", "whoami", "sleep", "wait",
		"exit", "return", "test", "[":
		return true
	default:
		return false
	}
}

func stripWrappers(argv []string, bg *bool) []string {
	for len(argv) > 0 {
		switch argv[0] {
		case "sudo":
			argv = skipSudo(argv[1:])
		case "nohup", "setsid":
			*bg = true
			argv = argv[1:]
		case "command", "exec", "time":
			argv = argv[1:]
		case "nice":
			argv = argv[1:]
			for len(argv) > 0 && strings.HasPrefix(argv[0], "-") {
				argv = argv[1:]
			}
		case "env":
			argv = argv[1:]
			for len(argv) > 0 && (isAssign(argv[0]) || strings.HasPrefix(argv[0], "-")) {
				if argv[0] == "-u" && len(argv) > 1 {
					argv = argv[2:]
					continue
				}
				argv = argv[1:]
			}
		default:
			if isAssign(argv[0]) {
				argv = argv[1:]
				continue
			}
			return argv
		}
	}
	return argv
}

func skipSudo(argv []string) []string {
	for len(argv) > 0 && strings.HasPrefix(argv[0], "-") {
		a := argv[0]
		argv = argv[1:]
		if a == "--" {
			break
		}
		switch a {
		case "-u", "-g", "-h", "-p", "-C", "-T", "--user", "--group", "--host", "--prompt":
			if len(argv) > 0 {
				argv = argv[1:]
			}
		}
	}
	return argv
}

func isAssign(s string) bool {
	if s == "" || s[0] == '-' || (s[0] >= '0' && s[0] <= '9') {
		return false
	}
	i := strings.IndexByte(s, '=')
	if i <= 0 {
		return false
	}
	for _, r := range s[:i] {
		if r != '_' && (r < 'A' || r > 'Z') && (r < 'a' || r > 'z') && (r < '0' || r > '9') {
			return false
		}
	}
	return true
}

func positionals(argv []string) []string {
	var out []string
	for i := 0; i < len(argv); i++ {
		a := argv[i]
		if a == "--" {
			out = append(out, argv[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "-") {
			continue
		}
		out = append(out, a)
	}
	return out
}

func (w *world) mv(args []string) {
	if len(args) < 2 {
		return
	}
	if len(args) == 2 {
		w.rename(args[0], args[1])
		return
	}
	dst := args[len(args)-1]
	for _, src := range args[:len(args)-1] {
		w.rename(src, clean(dst)+"/"+baseName(src))
	}
}

func (w *world) cp(args []string) {
	if len(args) < 2 {
		return
	}
	if len(args) == 2 {
		w.copyPath(args[0], args[1])
		return
	}
	dst := args[len(args)-1]
	for _, src := range args[:len(args)-1] {
		w.copyPath(src, clean(dst)+"/"+baseName(src))
	}
}

func (w *world) background(argv []string) {
	if len(argv) == 0 {
		return
	}
	detail := clip(strings.Join(argv, " "), 140)
	name := baseName(argv[0])
	if name == "" {
		return
	}
	port := portFromArgs(argv)
	kind := "process"
	if port != "" {
		kind = "http"
	}
	key := "Shell\x00" + detail
	if s := w.findKey(key); s != nil {
		s.State = Running
		s.Port = port
		s.Kind = kind
		return
	}
	w.svcs = append(w.svcs, &svc{
		Key: key, Name: name, Kind: kind, State: Running, Port: port, Detail: detail, Group: "Shell",
	})
}

func (w *world) docker(argv []string, bg bool) {
	for i := 1; i < len(argv); i++ {
		a := argv[i]
		switch a {
		case "compose":
			w.compose(argv[i+1:], bg)
			return
		case "container":
			continue
		case "run":
			w.dockerRun(argv[i+1:], bg)
			return
		case "start", "restart":
			w.markContainers(positionals(argv[i+1:]), Running)
			return
		case "stop", "kill", "rm":
			w.markContainers(positionals(argv[i+1:]), Stopped)
			return
		default:
			if strings.HasPrefix(a, "-") {
				if dockerGlobalValue(a) && !strings.Contains(a, "=") && i+1 < len(argv) {
					i++
				}
				continue
			}
			return
		}
	}
}

func dockerGlobalValue(a string) bool {
	switch a {
	case "-H", "--host", "--context", "--log-level", "-l", "--config", "--tlscacert", "--tlscert", "--tlskey":
		return true
	default:
		return false
	}
}

func (w *world) dockerRun(args []string, bg bool) {
	name, image, port, detach := parseRun(args)
	if !detach && !bg {
		return
	}
	if name == "" {
		name = imageBase(image)
	}
	if name == "" {
		return
	}
	detail := image
	if detail == "" {
		detail = name
	}
	for _, s := range w.svcs {
		if s.Kind == "container" && s.Name == name {
			s.State = Running
			if port != "" {
				s.Port = port
			}
			if image != "" {
				s.Detail = image
			}
			return
		}
	}
	w.svcs = append(w.svcs, &svc{
		Key: "Containers\x00" + name, Name: name, Kind: "container", State: Running,
		Port: port, Detail: detail, Group: "Containers",
	})
}

func parseRun(args []string) (name, image, port string, detach bool) {
	var pubs []string
	takes := map[string]bool{
		"-e": true, "--env": true, "-v": true, "--volume": true,
		"--network": true, "--net": true, "-w": true, "--workdir": true,
		"--restart": true, "--label": true, "-l": true, "--entrypoint": true,
		"-u": true, "--user": true, "--hostname": true, "-h": true,
		"--add-host": true, "--mount": true, "-m": true, "--memory": true,
		"--cpus": true, "--name": true, "-p": true, "--publish": true,
		"--env-file": true, "--platform": true, "--pull": true,
		"--health-cmd": true, "--log-driver": true, "--log-opt": true,
		"-c": true, "--cpu-shares": true, "--gpus": true, "--runtime": true,
		"--pid": true, "--ipc": true, "--ulimit": true, "--sysctl": true,
		"--tmpfs": true, "--device": true,
	}
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			if i+1 < len(args) {
				image = args[i+1]
			}
			break
		}
		if a == "" || !strings.HasPrefix(a, "-") {
			image = a
			break
		}
		if a == "-d" || a == "--detach" {
			detach = true
			continue
		}
		if strings.HasPrefix(a, "-p") && !strings.HasPrefix(a, "--") && a != "-p" {
			pubs = append(pubs, strings.TrimPrefix(a, "-p"))
			continue
		}
		if strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") && len(a) > 2 && !strings.Contains(a, "=") {
			if strings.Contains(a, "d") {
				detach = true
			}
			continue
		}
		switch {
		case a == "--name" && i+1 < len(args):
			i++
			name = args[i]
		case strings.HasPrefix(a, "--name="):
			name = strings.TrimPrefix(a, "--name=")
		case (a == "-p" || a == "--publish") && i+1 < len(args):
			i++
			pubs = append(pubs, args[i])
		case strings.HasPrefix(a, "--publish="):
			pubs = append(pubs, strings.TrimPrefix(a, "--publish="))
		default:
			if takes[a] && !strings.Contains(a, "=") && i+1 < len(args) {
				i++
			}
		}
	}
	return name, image, strings.Join(pubs, ", "), detach
}

func imageBase(image string) string {
	image = strings.TrimSpace(image)
	image = strings.Split(image, "@")[0]
	if i := strings.LastIndex(image, "/"); i >= 0 {
		image = image[i+1:]
	}
	if i := strings.Index(image, ":"); i >= 0 {
		image = image[:i]
	}
	return image
}

func (w *world) compose(args []string, bg bool) {
	file, verb, names, detach := parseComposeArgs(args)
	if bg {
		detach = true
	}
	path := w.resolveCompose(file)
	switch verb {
	case "up":
		if detach {
			w.composeSet(path, names, Running)
		}
	case "start", "restart":
		w.composeSet(path, names, Running)
	case "down", "stop":
		w.composeSet(path, names, Stopped)
	}
}

func parseComposeArgs(args []string) (file, verb string, names []string, detach bool) {
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "-f" || a == "--file":
			if i+1 < len(args) {
				i++
				file = args[i]
			}
		case strings.HasPrefix(a, "--file="):
			file = strings.TrimPrefix(a, "--file=")
		case a == "-d" || a == "--detach":
			detach = true
		case a == "--project-name" || a == "-p" || a == "--profile" || a == "--env-file" || a == "--project-directory" || a == "--progress":
			if i+1 < len(args) {
				i++
			}
		case a == "up" || a == "down" || a == "stop" || a == "start" || a == "restart":
			verb = a
			rest := args[i+1:]
			for j := 0; j < len(rest); j++ {
				r := rest[j]
				switch r {
				case "-d", "--detach":
					detach = true
				case "--build", "--wait", "--force-recreate", "--remove-orphans", "--no-deps", "--quiet-pull", "--abort-on-container-exit":
				case "--scale", "-t", "--timeout", "--exit-code-from":
					j++
				default:
					if strings.HasPrefix(r, "-") {
						continue
					}
					names = append(names, r)
				}
			}
			return
		}
	}
	return
}

func (w *world) composeSet(path string, names []string, state string) {
	svcs := w.servicesIn(path)
	if len(svcs) == 0 {
		if len(names) == 0 {
			names = []string{"compose"}
		}
		w.markContainers(names, state)
		return
	}
	want := map[string]bool{}
	for _, n := range names {
		want[n] = true
	}
	for _, s := range svcs {
		if len(want) == 0 || want[s.Name] {
			s.State = state
		}
	}
}

func (w *world) markContainers(names []string, state string) {
	for _, name := range names {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		var found bool
		for _, s := range w.svcs {
			if s.Kind == "container" && s.Name == name {
				s.State = state
				found = true
			}
		}
		if found {
			continue
		}
		w.svcs = append(w.svcs, &svc{
			Key: "Containers\x00" + name, Name: name, Kind: "container", State: state, Group: "Containers",
		})
	}
}

func (w *world) systemctl(args []string) {
	var now bool
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch a {
		case "--now":
			now = true
		case "--user", "-q", "--quiet", "--no-block", "--no-pager", "--system":
		default:
			if strings.HasPrefix(a, "-") {
				if systemctlValue(a) && !strings.Contains(a, "=") && i+1 < len(args) {
					i++
				}
				continue
			}
			pos = append(pos, a)
		}
	}
	if len(pos) == 0 {
		return
	}
	verb, names := pos[0], pos[1:]
	switch verb {
	case "start", "restart":
		w.markUnits(names, Running)
	case "stop":
		w.markUnits(names, Stopped)
	case "enable":
		if now {
			w.markUnits(names, Running)
		}
	case "disable":
		if now {
			w.markUnits(names, Stopped)
		}
	}
}

func systemctlValue(a string) bool {
	switch a {
	case "-H", "--host", "-M", "--machine", "-t", "--type", "--property":
		return true
	default:
		return false
	}
}

func (w *world) sysv(args []string) {
	pos := positionals(args)
	if len(pos) < 2 {
		return
	}
	switch pos[1] {
	case "start", "restart":
		w.markUnits([]string{pos[0]}, Running)
	case "stop":
		w.markUnits([]string{pos[0]}, Stopped)
	}
}

func (w *world) markUnits(names []string, state string) {
	for _, name := range names {
		name = strings.TrimSuffix(strings.TrimSpace(name), ".service")
		if name == "" || strings.ContainsAny(name, "*?[") {
			continue
		}
		var found bool
		for _, s := range w.svcs {
			if s.Kind == "unit" && s.Name == name {
				s.State = state
				found = true
			}
		}
		if found {
			continue
		}
		w.svcs = append(w.svcs, &svc{
			Key: "Units\x00" + name, Name: name, Kind: "unit", State: state, Group: "Units",
		})
	}
}

func (w *world) caddy(args []string, bg bool) {
	verb := ""
	for _, a := range args {
		if strings.HasPrefix(a, "-") {
			continue
		}
		verb = a
		break
	}
	switch verb {
	case "start":
		w.markCaddy(Running)
	case "stop":
		w.markCaddy(Stopped)
	case "run":
		if bg {
			w.markCaddy(Running)
		}
	default:
		if bg {
			w.background(append([]string{"caddy"}, args...))
		}
	}
}

func (w *world) markCaddy(state string) {
	var found bool
	for _, s := range w.svcs {
		if s.Kind == "http" && strings.EqualFold(baseName(s.Group), "Caddyfile") {
			s.State = state
			found = true
		}
	}
	if found {
		return
	}
	const key = "Caddy\x00caddy"
	if s := w.findKey(key); s != nil {
		s.State = state
		return
	}
	w.svcs = append(w.svcs, &svc{Key: key, Name: "caddy", Kind: "http", State: state, Group: "Caddy"})
}

func (w *world) node(argv []string, bg bool) bool {
	script, ok := nodeScript(argv)
	if !ok {
		return false
	}
	if !bg {
		return true
	}
	if w.markApp(argv) {
		return true
	}
	w.background(argv)
	return true
}

func nodeScript(argv []string) (string, bool) {
	if len(argv) == 0 {
		return "", false
	}
	var pos []string
	for i := 1; i < len(argv); i++ {
		a := argv[i]
		switch a {
		case "--prefix", "--cwd", "-C":
			i++
			continue
		}
		if strings.HasPrefix(a, "--prefix=") || strings.HasPrefix(a, "--cwd=") || strings.HasPrefix(a, "-") {
			continue
		}
		pos = append(pos, a)
	}
	if len(pos) == 0 {
		return "", false
	}
	switch argv[0] {
	case "npm", "pnpm", "yarn", "bun":
		if pos[0] == "run" && len(pos) > 1 {
			return pos[1], true
		}
		switch pos[0] {
		case "start", "dev", "serve":
			return pos[0], true
		}
	}
	return "", false
}

func (w *world) markApp(argv []string) bool {
	prefix := ""
	for i := 1; i < len(argv); i++ {
		switch argv[i] {
		case "--prefix", "--cwd", "-C":
			if i+1 < len(argv) {
				prefix = clean(argv[i+1])
			}
		}
		if strings.HasPrefix(argv[i], "--prefix=") {
			prefix = clean(strings.TrimPrefix(argv[i], "--prefix="))
		}
		if strings.HasPrefix(argv[i], "--cwd=") {
			prefix = clean(strings.TrimPrefix(argv[i], "--cwd="))
		}
	}
	var apps []*svc
	for _, s := range w.svcs {
		if s.Kind != "app" {
			continue
		}
		if prefix != "" && !strings.Contains(s.Group, prefix) {
			continue
		}
		apps = append(apps, s)
	}
	if len(apps) == 0 {
		return false
	}
	if len(apps) > 1 && prefix == "" {
		var pick *svc
		for i := len(w.order) - 1; i >= 0 && pick == nil; i-- {
			for _, s := range apps {
				if s.Group == w.order[i] {
					pick = s
					break
				}
			}
		}
		if pick == nil {
			return false
		}
		apps = []*svc{pick}
	}
	for _, s := range apps {
		s.State = Running
	}
	return true
}

func (w *world) kill(argv []string) {
	if len(argv) == 0 || argv[0] == "kill" {
		return
	}
	full := false
	var args []string
	for i := 1; i < len(argv); i++ {
		a := argv[i]
		if a == "-f" && argv[0] == "pkill" {
			full = true
			continue
		}
		if strings.HasPrefix(a, "-") {
			continue
		}
		args = append(args, a)
	}
	for _, pat := range args {
		if pat == "" {
			continue
		}
		for _, s := range w.svcs {
			if s.State != Running || (s.Kind != "process" && s.Kind != "http" && s.Kind != "app") {
				continue
			}
			if full {
				if strings.Contains(s.Detail, pat) || s.Name == pat {
					s.State = Stopped
				}
				continue
			}
			if s.Name == pat {
				s.State = Stopped
			}
		}
	}
}

func portFromArgs(argv []string) string {
	for i, a := range argv {
		switch a {
		case "--port", "--listen", "-l", "-p":
			if i+1 < len(argv) {
				if p := portToken(argv[i+1]); p != "" {
					return p
				}
			}
		}
		if strings.HasPrefix(a, "--port=") {
			if p := portToken(strings.TrimPrefix(a, "--port=")); p != "" {
				return p
			}
		}
		if a == "http.server" && i+1 < len(argv) && looksPort(argv[i+1]) {
			return argv[i+1]
		}
		if p := hostPort(a); p != "" {
			return p
		}
	}
	return ""
}

func portFromCommand(cmd string) string {
	if cmd == "" {
		return ""
	}
	cmds := parseCommands(cmd)
	if len(cmds) == 0 {
		return ""
	}
	return portFromArgs(cmds[0].argv)
}

func portToken(s string) string {
	s = strings.TrimPrefix(s, ":")
	if looksPort(s) || strings.Contains(s, ":") {
		return s
	}
	return ""
}

func hostPort(s string) string {
	if strings.HasPrefix(s, ":") && looksPort(s[1:]) {
		return s[1:]
	}
	host, port, ok := strings.Cut(s, ":")
	if !ok || !looksPort(port) {
		return ""
	}
	switch host {
	case "localhost", "127.0.0.1", "0.0.0.0", "[::1]", "[::]":
		return port
	default:
		return ""
	}
}

func looksPort(s string) bool {
	if s == "" || len(s) > 5 {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

package machine

import (
	"encoding/json"
	"strings"
)

func parseCompose(body string) []draft {
	lines := strings.Split(body, "\n")
	base, start := -1, 0
	for i, line := range lines {
		ind, rest := splitIndent(line)
		key, _, ok := yamlKey(rest)
		if ok && key == "services" {
			base, start = ind, i+1
			if ind == 0 {
				break
			}
		}
	}
	if base < 0 {
		return nil
	}
	var out []draft
	cur := -1
	svcIndent := -1
	portsIndent := -1
	inPorts := false
	for _, line := range lines[start:] {
		ind, rest := splitIndent(line)
		trim := strings.TrimSpace(rest)
		if trim == "" || strings.HasPrefix(trim, "#") {
			continue
		}
		if ind <= base {
			break
		}
		if inPorts && cur >= 0 && ind >= portsIndent && strings.HasPrefix(trim, "-") {
			item := yamlScalar(strings.TrimSpace(strings.TrimPrefix(trim, "-")))
			if item != "" && item != "|" && item != ">" {
				if out[cur].Port == "" {
					out[cur].Port = item
				} else {
					out[cur].Port += ", " + item
				}
			}
			continue
		}
		key, val, ok := yamlKey(rest)
		if !ok {
			continue
		}
		if svcIndent < 0 {
			svcIndent = ind
		}
		if ind == svcIndent {
			inPorts = false
			if key == "<<" {
				continue
			}
			out = append(out, draft{Name: key, Kind: "container"})
			cur = len(out) - 1
			continue
		}
		if cur < 0 || ind <= svcIndent {
			inPorts = false
			continue
		}
		switch key {
		case "ports":
			inPorts = true
			portsIndent = ind
		case "image":
			inPorts = false
			if val != "" {
				out[cur].Detail = val
			}
		case "build":
			inPorts = false
			if out[cur].Detail == "" {
				out[cur].Detail = "build"
			}
		default:
			inPorts = false
		}
	}
	return out
}

func parseUnit(path, body string) []draft {
	name := strings.TrimSuffix(baseName(path), ".service")
	if name == "" {
		return nil
	}
	var exec, desc string
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		k = strings.TrimSpace(k)
		v = strings.TrimSpace(v)
		if strings.EqualFold(k, "ExecStart") && exec == "" {
			exec = v
		}
		if strings.EqualFold(k, "Description") && desc == "" {
			desc = v
		}
	}
	detail := exec
	if detail == "" {
		detail = desc
	}
	return []draft{{
		Name: name, Kind: "unit", Detail: detail, Port: portFromCommand(exec),
	}}
}

func parseProcfile(body string) []draft {
	var out []draft
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		name, cmd, ok := strings.Cut(line, ":")
		name = strings.TrimSpace(name)
		cmd = strings.TrimSpace(cmd)
		if !ok || name == "" || strings.ContainsAny(name, " \t") {
			continue
		}
		out = append(out, draft{
			Name: name, Kind: "process", Detail: cmd, Port: portFromCommand(cmd),
		})
	}
	return out
}

func parseCaddy(body string) []draft {
	lines := strings.Split(body, "\n")
	var out []draft
	for i, line := range lines {
		ind, rest := splitIndent(line)
		if ind > 0 || rest == "" || strings.HasPrefix(rest, "#") {
			continue
		}
		addr := ""
		if strings.HasSuffix(rest, "{") {
			addr = strings.TrimSpace(strings.TrimSuffix(rest, "{"))
		} else if i+1 < len(lines) {
			_, next := splitIndent(lines[i+1])
			if strings.TrimSpace(next) == "{" {
				addr = strings.TrimSpace(rest)
			}
		}
		if !siteAddr(addr) {
			continue
		}
		out = append(out, draft{Name: addr, Kind: "http", Port: portOfAddr(addr), Detail: "caddy"})
	}
	return out
}

func parsePackage(path, body string) []draft {
	var pkg struct {
		Name    string         `json:"name"`
		Scripts map[string]any `json:"scripts"`
	}
	if json.Unmarshal([]byte(body), &pkg) != nil || len(pkg.Scripts) == 0 {
		return nil
	}
	var bits []string
	var port string
	for _, k := range []string{"start", "dev", "serve"} {
		s, _ := pkg.Scripts[k].(string)
		if s == "" {
			continue
		}
		bits = append(bits, k)
		if port == "" {
			port = portFromCommand(s)
		}
	}
	if len(bits) == 0 {
		return nil
	}
	name := strings.TrimSpace(pkg.Name)
	if name == "" {
		dir := parent(path)
		name = baseName(dir)
		if name == "" {
			name = "app"
		}
	}
	return []draft{{
		Name: name, Kind: "app", Port: port, Detail: strings.Join(bits, ", "),
	}}
}

func parent(path string) string {
	path = clean(path)
	i := strings.LastIndex(path, "/")
	if i < 0 {
		return ""
	}
	return path[:i]
}

func siteAddr(s string) bool {
	s = strings.TrimSpace(s)
	if s == "" || strings.ContainsAny(s, " \t") {
		return false
	}
	if strings.HasPrefix(s, ":") || strings.Contains(s, "://") || strings.Contains(s, ".") {
		return true
	}
	return strings.HasPrefix(s, "localhost")
}

func portOfAddr(s string) string {
	s = strings.TrimPrefix(s, "https://")
	s = strings.TrimPrefix(s, "http://")
	if strings.HasPrefix(s, ":") {
		p := strings.TrimPrefix(s, ":")
		if i := strings.IndexByte(p, ':'); i >= 0 {
			p = p[:i]
		}
		if looksPort(p) {
			return p
		}
	}
	if i := strings.LastIndex(s, ":"); i >= 0 && looksPort(s[i+1:]) {
		return s[i+1:]
	}
	return ""
}

func splitIndent(line string) (int, string) {
	i, n := 0, 0
	for i < len(line) {
		switch line[i] {
		case ' ':
			n++
			i++
		case '\t':
			n += 2
			i++
		default:
			return n, strings.TrimRight(line[i:], "\r")
		}
	}
	return n, ""
}

func yamlKey(s string) (key, rest string, ok bool) {
	s = strings.TrimSpace(s)
	if s == "" || strings.HasPrefix(s, "#") || strings.HasPrefix(s, "-") {
		return "", "", false
	}
	if s[0] == '"' || s[0] == '\'' {
		q := s[0]
		end := strings.IndexByte(s[1:], q)
		if end < 0 {
			return "", "", false
		}
		key = s[1 : 1+end]
		rest = strings.TrimSpace(s[2+end:])
		rest = strings.TrimPrefix(rest, ":")
		return key, yamlScalar(rest), key != ""
	}
	i := strings.IndexByte(s, ':')
	if i <= 0 {
		return "", "", false
	}
	key = strings.TrimSpace(s[:i])
	if key == "" || strings.ContainsAny(key, " \t{}[]") {
		return "", "", false
	}
	return key, yamlScalar(s[i+1:]), true
}

func yamlScalar(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	if s[0] == '"' || s[0] == '\'' {
		q := s[0]
		if end := strings.IndexByte(s[1:], q); end >= 0 {
			return s[1 : 1+end]
		}
	}
	if i := strings.IndexByte(s, '#'); i >= 0 {
		s = strings.TrimSpace(s[:i])
	}
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

