package machine

import (
	"encoding/json"
	"strings"
	"testing"
)

func TestComposeLifecycle(t *testing.T) {
	compose := "version: \"3\"\nservices:\n  web:\n    image: nginx\n    ports:\n      - \"8080:80\"\n  db:\n    image: postgres:16\n"
	up := snap(t,
		payload(write("compose.yaml", compose)),
		payload(bash("docker compose up -d")),
	)
	web := service(t, up, "web")
	if web.State != Running || web.Kind != "container" || web.Port != "8080:80" || web.Detail != "nginx" {
		t.Fatalf("%+v", web)
	}
	db := service(t, up, "db")
	if db.State != Running || db.Detail != "postgres:16" {
		t.Fatalf("%+v", db)
	}
	if up.Files[0].Path != "compose.yaml" || up.Files[0].Op != "write" {
		t.Fatalf("%+v", up.Files)
	}
	if !strings.Contains(up.Summary, "2 running") || !strings.Contains(up.Summary, "1 file") {
		t.Fatal(up.Summary)
	}

	one := snap(t, payload(
		write("compose.yaml", compose),
		bash("docker compose up -d web"),
	))
	if service(t, one, "web").State != Running || service(t, one, "db").State != Declared {
		t.Fatalf("%+v", one.Clusters)
	}

	down := snap(t,
		payload(write("compose.yaml", compose), bash("docker compose up -d")),
		payload(bash("docker compose down")),
	)
	if service(t, down, "web").State != Stopped || service(t, down, "db").State != Stopped {
		t.Fatalf("%+v", down.Clusters)
	}
}

func TestEditKeepsRunning(t *testing.T) {
	compose := "services:\n  web:\n    ports:\n      - \"8080:80\"\n"
	got := snap(t, payload(
		write("compose.yaml", compose),
		bash("docker compose up -d"),
		edit("compose.yaml", "8080:80", "9090:80"),
	))
	web := service(t, got, "web")
	if web.State != Running || web.Port != "9090:80" {
		t.Fatalf("%+v", web)
	}
	if got.Files[0].Op != "edit" {
		t.Fatal(got.Files[0])
	}
}

func TestDockerRunAndStop(t *testing.T) {
	got := snap(t, payload(
		bash(`docker run -d --name api -p 127.0.0.1:8080:80 -e FOO=bar nginx:alpine`),
		bash("docker stop api"),
	))
	api := service(t, got, "api")
	if api.State != Stopped || api.Kind != "container" || api.Port != "127.0.0.1:8080:80" || api.Detail != "nginx:alpine" {
		t.Fatalf("%+v", api)
	}
}

func TestUnitAndForeground(t *testing.T) {
	unit := "[Service]\nExecStart=/usr/bin/api --port 8080\n"
	got := snap(t, payload(
		write("deploy/api.service", unit),
		bash("npm start"),
		bash("systemctl start api"),
	))
	api := service(t, got, "api")
	if api.Kind != "unit" || api.State != Running || api.Port != "8080" {
		t.Fatalf("%+v", api)
	}
	stopped := snap(t, payload(
		write("deploy/api.service", unit),
		bash("systemctl start api"),
		bash("systemctl stop api"),
	))
	if service(t, stopped, "api").State != Stopped {
		t.Fatal(stopped.Clusters)
	}
}

func TestBackgroundPkillAndPackage(t *testing.T) {
	pkg := `{"name":"shop","scripts":{"start":"node server.js","dev":"node --watch server.js"}}`
	got := snap(t, payload(
		write("package.json", pkg),
		bash("npm start"),
		bash(`nohup python -m http.server 8080 >/tmp/h.log 2>&1 &`),
	))
	shop := service(t, got, "shop")
	if shop.Kind != "app" || shop.State != Declared || shop.Detail != "start, dev" {
		t.Fatalf("shop %+v", shop)
	}
	py := service(t, got, "python")
	if py.State != Running || py.Kind != "http" || py.Port != "8080" {
		t.Fatalf("python %+v", py)
	}

	started := snap(t, payload(
		write("package.json", pkg),
		bash(`nohup npm start >/dev/null 2>&1 &`),
	))
	if service(t, started, "shop").State != Running {
		t.Fatal(started.Clusters)
	}

	killed := snap(t, payload(
		bash(`nohup python -m http.server 8080 >/tmp/h.log 2>&1 &`),
		bash("pkill -f http.server"),
	))
	if service(t, killed, "python").State != Stopped {
		t.Fatal(killed.Clusters)
	}
}

func TestCaddyProcfileAndRemove(t *testing.T) {
	caddy := ":8080 {\n\treverse_proxy localhost:3000\n}\n"
	proc := "web: bundle exec puma -p 3000\n"
	got := snap(t, payload(
		write("Caddyfile", caddy),
		write("Procfile", proc),
		bash("caddy start"),
	))
	if service(t, got, ":8080").State != Running || service(t, got, ":8080").Port != "8080" {
		t.Fatalf("caddy %+v", got.Clusters)
	}
	if service(t, got, "web").State != Declared || service(t, got, "web").Port != "3000" {
		t.Fatalf("proc %+v", got.Clusters)
	}

	gone := snap(t, payload(
		write("compose.yaml", "services:\n  web:\n    image: nginx\n"),
		bash("rm -f compose.yaml"),
	))
	if len(gone.Clusters) != 0 || len(gone.Files) != 0 {
		t.Fatalf("%+v", gone)
	}

	kept := snap(t, payload(
		write("compose.yaml", "services:\n  web:\n    image: nginx\n"),
		bash("docker compose up -d"),
		bash("rm -f compose.yaml"),
	))
	if service(t, kept, "web").State != Running {
		t.Fatalf("%+v", kept)
	}
	if len(kept.Files) != 0 {
		t.Fatal(kept.Files)
	}
}

func TestQuotedCommandFailedToolAndAgents(t *testing.T) {
	got := snap(t, payload(
		write("compose.yaml", "services:\n  web:\n    image: nginx\n"),
		bash(`bash -lc "docker compose up -d || true"`),
		bash("echo should-not-be-a-service"),
	))
	if service(t, got, "web").State != Running {
		t.Fatal(got.Clusters)
	}

	failed := snap(t, payload(tool("write", "ERROR", map[string]any{
		"path": "compose.yaml", "content": "services:\n  web:\n    image: nginx\n",
	})))
	if len(failed.Clusters) != 0 || len(failed.Files) != 0 {
		t.Fatal(failed)
	}

	runs := []Run{
		{InstallID: 1, Install: "laptop", Payload: []byte(payload(bash("docker run -d --name api nginx")))},
		{InstallID: 2, Install: "ci", Payload: []byte(payload(bash("docker run -d --name worker redis")))},
	}
	both := Replay(runs)
	if len(both) != 2 || both[0].Agent != "laptop" || both[1].Agent != "ci" {
		t.Fatalf("%+v", both)
	}
	if service(t, both[0], "api").State != Running || service(t, both[1], "worker").Detail != "redis" {
		t.Fatalf("%+v / %+v", both[0], both[1])
	}
}

func TestRedirectAndOr(t *testing.T) {
	got := parseCommands(`nohup python -m http.server 8080 >/tmp/h.log 2>&1 &`)
	if len(got) != 1 || !got[0].bg {
		t.Fatalf("%+v", got)
	}
	if strings.Join(got[0].argv, " ") != "nohup python -m http.server 8080" {
		t.Fatalf("%q", got[0].argv)
	}
	or := parseCommands(`docker compose up -d || true`)
	if len(or) != 1 || strings.Join(or[0].argv, " ") != "docker compose up -d" {
		t.Fatalf("%+v", or)
	}
}

func snap(t *testing.T, payloads ...string) Snapshot {
	t.Helper()
	var runs []Run
	for _, p := range payloads {
		runs = append(runs, Run{InstallID: 1, Install: "laptop", Payload: []byte(p)})
	}
	got := Replay(runs)
	if len(got) != 1 {
		t.Fatalf("snapshots: %d", len(got))
	}
	return got[0]
}

func service(t *testing.T, sn Snapshot, name string) Service {
	t.Helper()
	var found Service
	n := 0
	for _, c := range sn.Clusters {
		for _, s := range c.Services {
			if s.Name == name {
				found = s
				n++
			}
		}
	}
	if n != 1 {
		t.Fatalf("service %s found %d times in %+v", name, n, sn.Clusters)
	}
	return found
}

func payload(tools ...map[string]any) string {
	root := map[string]any{"name": "run", "kind": "WORKFLOW", "children": tools}
	b, err := json.Marshal(root)
	if err != nil {
		panic(err)
	}
	return string(b)
}

func write(path, content string) map[string]any {
	return tool("write", "OK", map[string]any{"path": path, "content": content})
}

func edit(path, old, new string) map[string]any {
	return tool("edit", "OK", map[string]any{"path": path, "oldText": old, "newText": new})
}

func bash(command string) map[string]any {
	return tool("bash", "OK", map[string]any{"command": command})
}

func tool(name, status string, input map[string]any) map[string]any {
	return map[string]any{
		"kind": "TOOL", "name": name, "tool_name": name, "status": status, "input": input,
	}
}

