// TracePayload is one stored run, oldest-first when listed for replay.
type TracePayload struct {
	InstallID int64
	Install   string
	Payload   string
}

// ListPayloads returns the newest limit runs of each agent, oldest first.
// The machine map replays them in that order. Payloads for other accounts
// are not returned.
func (s *Store) ListPayloads(ctx context.Context, accountID int64, limit int) ([]TracePayload, error) {
	if limit < 1 || limit > 100 {
		limit = 20
	}
	rows, err := s.db.QueryContext(ctx, `
		SELECT install_id, name, payload
		FROM (
			SELECT t.install_id AS install_id, i.name AS name, t.payload AS payload,
			       t.received_at AS received_at, t.id AS id,
			       ROW_NUMBER() OVER (
			           PARTITION BY t.install_id
			           ORDER BY t.received_at DESC, t.id DESC
			       ) AS n
			FROM traces t
			JOIN installs i ON i.id = t.install_id
			WHERE t.account_id = ?
		)
		WHERE n <= ?
		ORDER BY received_at ASC, id ASC`, accountID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []TracePayload
	for rows.Next() {
		var p TracePayload
		if err := rows.Scan(&p.InstallID, &p.Install, &p.Payload); err != nil {
			return nil, err
		}
		out = append(out, p)
	}
	return out, rows.Err()
}

// ListTraces returns the newest traces for an account, without payloads.

	Traces        []traceView
	Detail        *detailView
	Machines      []machineView
}

type machineView struct {
	Agent    string
	Summary  string
	Clusters []clusterView
	Files    []fileView
}

type clusterView struct {
	Title    string
	Services []serviceView
}

type serviceView struct {
	Name   string
	Kind   string
	State  string
	Port   string
	Detail string
}

type fileView struct {
	Path string
	Op   string
}

func toMachines(rows []store.TracePayload, accountNumber string) []machineView {
	runs := make([]machine.Run, len(rows))
	for i, row := range rows {
		runs[i] = machine.Run{InstallID: row.InstallID, Install: row.Install, Payload: []byte(row.Payload)}
	}
	var out []machineView
	for _, sn := range machine.Replay(runs) {
		out = append(out, machineView{
			Agent:    redactAccount(sn.Agent, accountNumber),
			Summary:  sn.Summary,
			Clusters: redactClusters(sn.Clusters, accountNumber),
			Files:    redactFiles(sn.Files, accountNumber),
		})
	}
	return out
}

func redactClusters(clusters []machine.Cluster, number string) []clusterView {
	var out []clusterView
	for _, c := range clusters {
		cv := clusterView{Title: redactAccount(c.Title, number)}
		for _, s := range c.Services {
			cv.Services = append(cv.Services, serviceView{
				Name:   redactAccount(s.Name, number),
				Kind:   s.Kind,
				State:  s.State,
				Port:   redactAccount(s.Port, number),
				Detail: redactAccount(s.Detail, number),
			})
		}
		out = append(out, cv)
	}
	return out
}

func redactFiles(files []machine.File, number string) []fileView {
	var out []fileView
	for _, f := range files {
		out = append(out, fileView{Path: redactAccount(f.Path, number), Op: f.Op})
	}
	return out
}

func toDetail(tr store.Trace, accountNumber string) *detailView {

	v := buildView(s.cfg, sess, flash, installs, traces)
	rows, err := s.store.ListPayloads(r.Context(), sess.AccountID, machineRuns)
	if err != nil {
		return view{}, err
	}
	v.Machines = toMachines(rows, sess.Number)
	return v, nil
}

func (s *Server) machine(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.session(w, r)
	if !ok {
		if hx(r) {
			w.Header().Set("HX-Redirect", "/")
			w.WriteHeader(http.StatusOK)
			return
		}
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	if !hx(r) {
		v, err := s.dashboardView(r, sess, store.Flash{})
		if err != nil {
			s.fail(w, err)
			return
		}
		s.render(w, "dashboard", v, http.StatusOK)
		return
	}
	rows, err := s.store.ListPayloads(r.Context(), sess.AccountID, machineRuns)
	if err != nil {
		s.fail(w, err)
		return
	}
	s.render(w, "machine", view{Machines: toMachines(rows, sess.Number)}, http.StatusOK)
}

