func TestListPayloadsPerAgent(t *testing.T) {
	s := testOpen(t)
	ctx := context.Background()
	acc, _, err := s.CreateAccount(ctx)
	if err != nil {
		t.Fatal(err)
	}
	laptop, _, err := s.CreateInstall(ctx, acc.ID, "laptop")
	if err != nil {
		t.Fatal(err)
	}
	ci, _, err := s.CreateInstall(ctx, acc.ID, "ci")
	if err != nil {
		t.Fatal(err)
	}
	insert := func(id int64, payload string) {
		t.Helper()
		if _, err := s.InsertTrace(ctx, NewTrace{
			AccountID: acc.ID, InstallID: id, Workflow: "run", Status: "OK", Payload: payload,
		}); err != nil {
			t.Fatal(err)
		}
	}
	insert(laptop.ID, "first")
	insert(laptop.ID, "second")
	insert(ci.ID, "other")
	if _, err := s.InsertTrace(ctx, NewTrace{Workflow: "anon", Status: "OK", Payload: "secret"}); err != nil {
		t.Fatal(err)
	}
	latest, err := s.ListPayloads(ctx, acc.ID, 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(latest) != 2 || latest[0].Payload != "second" || latest[0].Install != "laptop" || latest[1].Payload != "other" {
		t.Fatalf("%+v", latest)
	}
	all, err := s.ListPayloads(ctx, acc.ID, 20)
	if err != nil || len(all) != 3 || all[0].Payload != "first" || all[1].Payload != "second" || all[2].Payload != "other" {
		t.Fatalf("%+v %v", all, err)
	}
}

