func TestMachineMap(t *testing.T) {
	ts, _ := newServer(t, neatlogs.Disabled{}, config.Config{
		PublicURL: "http://127.0.0.1:8080",
		BodyLimit: 1 << 20,
	})
	client := newClient(t)
	page := createAccount(t, client, ts.URL)
	if !strings.Contains(page, "Nothing mapped yet.") || !strings.Contains(page, "latest 20 runs") {
		t.Fatal("missing machine section")
	}
	keyPage := postForm(t, client, ts.URL+"/installs", url.Values{
		"csrf": {match(t, page, `name="csrf" value="([^"]+)"`)},
		"name": {"laptop"},
	})
	key := match(t, keyPage, `shy_[A-Za-z0-9_-]{40,}`)
	body, err := json.Marshal(map[string]any{
		"name": "run",
		"children": []any{
			map[string]any{
				"kind": "TOOL", "name": "write", "tool_name": "write", "status": "OK",
				"input": map[string]any{
					"path":    "compose.yaml",
					"content": "services:\n  web:\n    image: nginx\n    ports:\n      - \"8080:80\"\n",
				},
			},
			map[string]any{
				"kind": "TOOL", "name": "bash", "tool_name": "bash", "status": "OK",
				"input": map[string]any{"command": "docker compose up -d"},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	res := postJSON(t, ts.URL+"/v1/trace", key, string(body))
	defer res.Body.Close()
	if res.StatusCode != http.StatusOK {
		t.Fatalf("ingest %d %s", res.StatusCode, readAll(t, res))
	}
	page = get(t, client, ts.URL+"/")
	if !strings.Contains(page, `class="svc svc-running"`) || !strings.Contains(page, `svc-name">web<`) || !strings.Contains(page, "8080:80") || !strings.Contains(page, "nginx") {
		t.Fatal(page)
	}
	req, err := http.NewRequest(http.MethodGet, ts.URL+"/machine", nil)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("HX-Request", "true")
	res, err = client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer res.Body.Close()
	partial := string(readAll(t, res))
	if res.StatusCode != http.StatusOK || !strings.Contains(partial, `id="machine"`) || strings.Contains(partial, "<html") {
		t.Fatalf("partial %d %s", res.StatusCode, partial)
	}
	if !strings.Contains(partial, `svc-name">web<`) {
		t.Fatal(partial)
	}
}

